const data = $json.body;

const message = data.msg?.text?.body;
let phone = data.msg?.from;
const contactName = data.msg?.pushName || data.contact?.name || '';

if (!message || !phone) {
  return [{ ignore: true }];
}

phone = phone.replace(/\D/g, '');
if (!phone.startsWith('55')) {
  phone = '55' + phone;
}

return [{
  phone,
  contactName,
  chatInput: message,
  sessionId: phone,
  ignore: false
}];

const phone = $node['Format Input'].json.phone;
const contactName = $node['Format Input'].json.contactName || '';
const output = String($json.output || '');

const marker = /```avalia\s*([\s\S]*?)\s*```/i;
const match = output.match(marker);

let replyText = output.replace(marker, '').trim();
let sendToAvalia = false;
let avaliaPayload = null;

if (match) {
  try {
    const parsed = JSON.parse(match[1].trim());
    const eventId = `avalia_${phone}_${Date.now()}`;

    avaliaPayload = {
      eventId,
      name: parsed.name || contactName || 'Lead WhatsApp',
      phone,
      interest: parsed.interest || 'Avaliação via WhatsApp',
      propertyType: parsed.propertyType,
      location: parsed.location || parsed.propertyInput?.address,
      propertyInput: parsed.propertyInput || null,
      evaluationResult: parsed.evaluationResult || null
    };

    sendToAvalia = Boolean(
      avaliaPayload.location &&
      avaliaPayload.evaluationResult?.estimatedValue
    );
  } catch (error) {
    sendToAvalia = false;
  }
}

return [{
  phone,
  replyText,
  sendToAvalia,
  avaliaPayload
}];

const phone = $node['Format Input'].json.phone;
const replyText = $node['Extrair Avaliação'].json.replyText;

return [{
  number: phone,
  body: replyText,
  externalKey: 'avalia_' + phone,
  isClosed: false
}];
